import type { TurnTally } from '../types'

const SIZE_LEVELS = [150, 400, 1000]
const FILES_NAMED = 12

export const sizeLevel = (lines: number) => SIZE_LEVELS.filter(level => lines >= level).length

export const sizeNote = (lines: number, files: number) =>
  `Uncommitted change is now ${lines} lines in ${files} ${files === 1 ? 'file' : 'files'}. Commit a slice, or run /gate to see the risk.`

const GUIDE = `Give me a reading guide for the changes you made in your last turn. Do not change any files.

1. The behaviour that changed, in one sentence.
2. The entry point and the call path from it, each step as file:line.
3. The two or three files I should read closely, and which of the rest are mechanical.
4. The invariants the new code relies on.
5. What you deliberately left untouched, and why.`

export const emptyTally = (): TurnTally => ({ lines: 0, files: [] })

const lineCount = (text: string) => (text === '' ? 0 : text.split(/\r?\n/).length)

export const addWrite = (held: TurnTally, path: string, text: string): TurnTally => ({
  lines: held.lines + lineCount(text),
  files: held.files.includes(path) ? held.files : [...held.files, path],
})

export function guidePrompt(files: string[]): string {
  if (files.length === 0) {
    return GUIDE
  }

  const named = files.slice(0, FILES_NAMED).join('\n')
  const more = files.length > FILES_NAMED ? `\nand ${files.length - FILES_NAMED} more` : ''

  return `${GUIDE}\n\nThe files you changed:\n${named}${more}`
}

files.hooks/jev.ts:
import type { Blast, Jev, Judgment, Place } from '../types'
import { tagHunks } from './hunks'
import type { Hunk } from './hunks'

export const JEV_URL = 'https://api.typesafe.ai/v1/systemone'
export const PATCH_CHARS = 60_000
/** Pinned, not `jev-latest`: the thresholds below were tuned on 1.13, and `jev-latest` moves without notice. */
export const JEV_MODEL = 'jev-1.13.0'

const yesNo = (instructions: string, yes: string, no: string) => ({
  type: 'noul',
  instructions,
  criteria: { true: yes, false: no },
})

export const QUESTIONS = {
  behaviour: yesNo(
    'Does this diff change behaviour that a user or a caller of this code can observe?',
    'Inputs, outputs, errors, side effects or what a person sees differ after this diff.',
    'Only refactoring, renaming, formatting, comments or documentation.',
  ),
  security: yesNo(
    'Does this diff change authentication, authorization, secrets, input validation or other security-relevant code?',
    'Code that decides who may do what, handles credentials, or validates untrusted input changed.',
    'No security-relevant code changed.',
  ),
  data: yesNo(
    'Does this diff change how data is stored, migrated, deleted or what its schema is?',
    'Persistence, schemas, migrations or deletion of stored data changed.',
    'Stored data and its shape are untouched.',
  ),
  money: yesNo(
    'Does this diff change payments, billing, prices or monetary calculations?',
    'Code that charges, refunds, prices or sums money changed.',
    'No code that handles money changed.',
  ),
  concurrency: yesNo(
    'Does this diff change concurrency, locking, retries, caching or timing?',
    'Threads, async ordering, locks, retries, caches or timeouts changed.',
    'Nothing about ordering, timing or caching changed.',
  ),
  publicApi: yesNo(
    'Does this diff change an interface other code depends on: an exported signature, an HTTP endpoint, a CLI flag or a file format?',
    'Something other code or other people call or read changed shape.',
    'Only internal code changed.',
  ),
  tested: yesNo(
    'Does this diff add or change tests that exercise the behaviour it changes?',
    'Test files in the diff cover the changed behaviour.',
    'The diff has no tests for what it changes.',
  ),
  mixed: yesNo(
    'Does this diff mix unrelated changes that would be easier to review separately?',
    'It holds several unrelated changes.',
    'It is one coherent change.',
  ),
  readability: {
    type: 'score',
    instructions: 'How hard is this diff for a reviewer to read and understand?',
    criteria: [
      'Clear: small steps, good names, intent obvious from the code.',
      'Mostly clear: a few spots need a second look.',
      'Effortful: dense logic or unclear names; the intent needs explaining.',
      'Hard: tangled control flow, several concerns interleaved, intent unclear.',
    ],
  },
} as const

export const LABELS: Record<string, string> = {
  behaviour: 'changes behaviour',
  security: 'security',
  data: 'stored data',
  money: 'money',
  concurrency: 'concurrency',
  publicApi: 'public interface',
  tested: 'has tests',
  mixed: 'mixes changes',
}

/** What each signal measures, in the words the pane shows under it. */
export const MEANS: Record<string, string> = {
  behaviour: 'Whether a user or caller would notice a difference: inputs, outputs, errors, side effects.',
  security: 'Code that decides who may do what, handles credentials, or validates untrusted input.',
  data: 'How data is stored or migrated, its schema, or deleting it.',
  money: 'Charging, refunds, prices or sums of money.',
  concurrency: 'Ordering, locks, retries, caches or timeouts.',
  publicApi: 'Something other code or people depend on: an exported signature, endpoint, CLI flag or file format.',
  tested: 'Whether test files in the diff exercise the behaviour it changes.',
  untested: 'A user or caller would notice a difference, and no test in the diff exercises it.',
  mixed: 'Several unrelated changes that would be easier to review apart.',
  readability: 'How much effort a reviewer needs to follow the diff.',
}

/** The signals worth a "where": each gets a choice among the diff's hunks, asked in the same request. */
const WHERE_KEYS = ['behaviour', 'security', 'data', 'money', 'concurrency', 'publicApi'] as const
const NO_HUNK = 'none'
/** Weight spreads over hunks on a wide diff: on a 45-hunk one, a clear public-interface hunk drew 0.44 for its file. */
const WHERE_SURE = 0.4

/**
 * No "no single hunk" option: given one, Jev took it on a wide diff even for signals it rated likely. A nudge
 * towards code over docs spread the answers further, so it was left out.
 */
const whereQuestion = (premise: string, hunks: Hunk[]) => ({
  type: 'choice',
  instructions: `Suppose this holds for the diff: ${premise} Each hunk in \`diff\` starts with a tag such as H01|. Which hunk shows it most clearly?`,
  criteria: { ...Object.fromEntries(hunks.map(hunk => [hunk.id, null])), [NO_HUNK]: 'Nothing in the diff does this.' },
})

/**
 * The questions for this change: the fixed ones, plus a "which hunk" for each signal and for readability. They ride
 * in the same request: only input is billed, and the options are tags, so a "where" adds little. Options keep diff
 * order, since Jev leans toward the first option. A one-hunk change needs none.
 */
export function questionsOf(hunks: Hunk[]) {
  if (hunks.length < 2) {
    return QUESTIONS
  }

  const wheres = WHERE_KEYS.map(key => [`${key}At`, whereQuestion(QUESTIONS[key].criteria.true, hunks)])

  return {
    ...QUESTIONS,
    ...Object.fromEntries(wheres),
    hardestAt: whereQuestion('Some of it is hard for a reviewer to read and understand.', hunks),
  }
}

/** The request, and the hunks its tags stand for, to read the answers back with. */
export function askOf(blast: Blast, patch: string, model = JEV_MODEL) {
  const { tagged, hunks } = tagHunks(patch)
  const body = JSON.stringify({
    model,
    state: {
      changed_files: blast.files.map(file => file.path),
      diff: tagged,
    },
    questions: questionsOf(hunks),
  })

  return { body, hunks }
}

type RawAnswer = { type?: string; noul?: number; choice?: string; probabilities?: Record<string, number> }

/**
 * Where a "which hunk" answer points: the file that holds at least `WHERE_SURE` across its hunks and more than "none"
 * does, and the line of its top hunk when that hunk holds more than half the file's weight. With one hunk there was
 * no question to ask.
 */
function placeOf(answer: RawAnswer | undefined, hunks: Hunk[]): Place | undefined {
  const [only] = hunks

  if (hunks.length === 1 && only !== undefined) {
    return { path: only.path, line: only.line }
  }

  const shares = answer?.probabilities ?? {}
  const byFile = new Map<string, { weight: number; top?: Hunk; topShare: number }>()

  for (const hunk of hunks) {
    const share = shares[hunk.id] ?? 0
    const file = byFile.get(hunk.path) ?? { weight: 0, topShare: 0 }
    byFile.set(hunk.path, {
      weight: file.weight + share,
      ...(share > file.topShare ? { top: hunk, topShare: share } : { top: file.top, topShare: file.topShare }),
    })
  }

  const [path, best] = [...byFile].sort(([, a], [, b]) => b.weight - a.weight)[0] ?? []

  if (path === undefined || best === undefined || best.weight < WHERE_SURE || best.weight <= (shares[NO_HUNK] ?? 0)) {
    return undefined
  }

  return best.top !== undefined && best.topShare > best.weight / 2 ? { path, line: best.top.line } : { path }
}

/** A place as a reviewer types it: `path:line`, or the path alone. */
export const placeText = (at: Place) => (at.line === undefined ? at.path : `${at.path}:${at.line}`)

const tokensOf = (value: unknown) => {
  const usage = typeof value === 'object' && value !== null && 'usage' in value ? value.usage : undefined
  const input = typeof usage === 'object' && usage !== null && 'input_tokens' in usage ? usage.input_tokens : undefined

  return typeof input === 'number' ? input : undefined
}

const asAnswers = (value: unknown): Record<string, RawAnswer> | undefined =>
  typeof value === 'object' && value !== null && 'answers' in value
    ? (value.answers as Record<string, RawAnswer>)
    : undefined

export function parseJev(status: number, text: string, hunks: Hunk[] = []): Exclude<Jev, { status: 'off' }> {
  if (status === 401) {
    return { status: 'failed', note: 'Jev refused the API key (401).' }
  }

  if (status === 429 || status === 529) {
    return { status: 'failed', note: `Jev is busy (${status}); triage used blast radius only.` }
  }

  if (status < 200 || status >= 300) {
    return { status: 'failed', note: `Jev answered ${status}.` }
  }

  let answers: Record<string, RawAnswer> | undefined
  let tokens: number | undefined

  try {
    const parsed: unknown = JSON.parse(text)
    answers = asAnswers(parsed)
    tokens = tokensOf(parsed)
  } catch {
    answers = undefined
  }

  if (answers === undefined) {
    return { status: 'failed', note: 'Jev sent an answer triage could not read.' }
  }

  const judgments: Judgment[] = Object.keys(LABELS).flatMap(key => {
    const value = answers?.[key]?.noul
    const at = placeOf(answers?.[`${key}At`], hunks)

    return typeof value === 'number' ? [{ key, label: LABELS[key] ?? key, value, ...(at === undefined ? {} : { at }) }] : []
  })
  const levels = Object.entries(answers.readability?.probabilities ?? {}).sort(
    ([a], [b]) => Number(a) - Number(b),
  )
  const hardToRead = levels.slice(-2).reduce((sum, [, share]) => sum + share, 0)
  const hardestAt = placeOf(answers.hardestAt, hunks)

  return {
    status: 'judged',
    judgments,
    hardToRead,
    ...(hardestAt === undefined ? {} : { hardestAt }),
    ...(tokens === undefined ? {} : { tokens }),
  }
}

files.hooks/pane.tsx:
import type { Elements, RenderInput } from 'claude-code'

import type { Flag, Review, Triage } from '../types'
import { startWith } from './blast'
import { MEANS, placeText } from './jev'
import { BADGE, changeLine, coverageOf, diagnosticsOf, reviewHeadline, subjectKey } from './report'
import { fixPrompt, tookOf } from './review'
import { clearOf, flagsOf, groupsLine, testsNoteOf } from './verdict'

export type PaneView = {
  judged: Triage | null
  reviewed: Review
  isApproved: boolean
  isOpen: boolean
  isScrollHinted: boolean
}

export type PaneActions = {
  approve: (fingerprint: string) => Promise<unknown>
  toggleDetails: () => Promise<unknown>
  triage: () => Promise<unknown>
  codex: () => Promise<unknown>
  send: (text: string) => Promise<unknown>
}

export function paneOf(ui: Elements[RenderInput<'Pane'>['surface']], view: PaneView, act: PaneActions) {
  const { Box, Button, Text } = ui
  const { judged, reviewed, isApproved, isOpen } = view

  const isOtherChange =
    reviewed.status === 'done' &&
    reviewed.subject !== undefined &&
    judged?.subject !== undefined &&
    subjectKey(judged.subject) !== reviewed.subject
  const isStale =
    !isOtherChange &&
    reviewed.status === 'done' &&
    (reviewed.isEdited === true ||
      (judged !== null && reviewed.fingerprint !== undefined && reviewed.fingerprint !== judged.fingerprint))
  const reviewBox = (
    <Box flexDirection="column">
      {reviewed.status === 'running' && (
        <Box flexDirection="column" marginTop={1} borderStyle="round" borderColor="suggestion" paddingX={1}>
          <Box>
            <Text bold color="suggestion">
              Codex is reviewing…
            </Text>
            <Box flexGrow={1} />
            <Text dimColor>{tookOf(reviewed.tookMs)}</Text>
          </Box>
          <Text dimColor wrap="truncate-end">
            {reviewed.doing ?? 'Starting Codex. A review usually takes a few minutes.'}
          </Text>
          <Text dimColor wrap="wrap">
            Reviewing {reviewed.covers}. This run is billed to your Codex account.
          </Text>
        </Box>
      )}

      {isOtherChange && (
        <Box marginTop={1}>
          <Text dimColor wrap="wrap">
            An earlier Codex review covered a different change. Run Codex review to check this one.
          </Text>
        </Box>
      )}

      {reviewed.status === 'done' && !isOtherChange && (
        <Box
          flexDirection="column"
          marginTop={1}
          borderStyle="round"
          borderColor={reviewed.findings.length > 0 || !reviewed.isClean ? 'warning' : 'subtle'}
          paddingX={1}
        >
          <Box>
            <Text bold color={reviewed.findings.length > 0 || !reviewed.isClean ? 'warning' : 'success'}>
              {reviewHeadline(reviewed)}
            </Text>
            <Box flexGrow={1} />
            <Text dimColor>{tookOf(reviewed.tookMs)}</Text>
          </Box>
          <Text dimColor wrap="wrap">
            Covered {reviewed.covers}.
          </Text>
          {reviewed.brief !== undefined && (
            <Box flexDirection="column">
              <Text dimColor>Codex was told this is what was built:</Text>
              <Text dimColor wrap="wrap">
                {reviewed.brief}
              </Text>
            </Box>
          )}
          {isStale && (
            <Text color="warning" wrap="wrap">
              ▲ The change has been edited since this review. Run it again.
            </Text>
          )}
          {reviewed.summary !== '' && <Text wrap="wrap">{reviewed.summary}</Text>}
          {reviewed.findings.map(one => (
            <Box flexDirection="column" marginTop={1}>
              <Box>
                <Text bold color={one.priority === 'P1' ? 'error' : 'warning'}>
                  {one.priority}{' '}
                </Text>
                <Box flexShrink={1}>
                  <Text bold wrap="wrap">
                    {one.title}
                  </Text>
                </Box>
              </Box>
              <Text color="suggestion" wrap="truncate-end">
                ↳ {one.at}
              </Text>
              <Text dimColor wrap="wrap">
                {one.body}
              </Text>
            </Box>
          ))}
          {reviewed.findings.length > 0 && (
            <Box marginTop={1}>
              <Button
                key="fix"
                label="Send to Claude"
                variant="primary"
                onPress={async () => {
                  await act.send(fixPrompt(reviewed.findings))
                }}
              />
            </Box>
          )}
        </Box>
      )}
    </Box>
  )

  if (judged === null) {
    return (
      <Box flexDirection="column">
        <Text dimColor wrap="wrap">
          Nothing triaged yet. Triage runs when Claude commits, or type /gate.
        </Text>
        {reviewBox}
      </Box>
    )
  }

  const badge = BADGE[judged.verdict]
  const isOutdated = judged.isEdited === true
  const { jev } = judged
  const isWhole = jev.status === 'judged' && !judged.isPatchCut
  const heading = (text: string) => (
    <Box marginTop={1}>
      <Text bold>{text}</Text>
    </Box>
  )
  const flags = flagsOf(judged.blast, jev)
  const clear = clearOf(jev)
  const testsNote = testsNoteOf(jev)
  const flagged = (flag: Flag) => (
    <Box key={flag.key} flexDirection="column" marginTop={1}>
      <Box>
        <Box flexGrow={1} flexShrink={1}>
          <Text wrap="truncate-end">{flag.label}</Text>
        </Box>
        <Text color={flag.isLikely ? 'error' : 'warning'}>{flag.isLikely ? 'likely' : 'possible'}</Text>
      </Box>
      <Text dimColor wrap="wrap">
        {MEANS[flag.key] ?? ''}
      </Text>
      {flag.at !== undefined && (
        <Text color="suggestion" wrap="truncate-start">
          ↳ {placeText(flag.at)}
        </Text>
      )}
      {flag.groups !== undefined && (
        <Text color="suggestion" wrap="wrap">
          ↳ {groupsLine(flag.groups)}
        </Text>
      )}
    </Box>
  )

  return (
    <Box flexDirection="column">
      <Box>
        <Text color={badge.tone} bold>
          {badge.mark} {badge.word}
        </Text>
        <Box flexGrow={1} />
        {isApproved && <Text color="success">approved</Text>}
      </Box>
      <Text dimColor wrap="wrap">
        {badge.means}
      </Text>
      <Text wrap="wrap">{changeLine(judged)}</Text>
      <Text color={isWhole ? undefined : 'warning'} dimColor={isWhole} wrap="wrap">
        {coverageOf(judged)}
      </Text>
      {isOutdated && (
        <Text color="warning" wrap="wrap">
          ▲ The change has been edited since this assessment. Refresh it.
        </Text>
      )}
      {judged.verdict === 'hold' && isApproved && !isOutdated && (
        <Text color="success" wrap="wrap">
          Approved. The request to commit is in your prompt box: press Enter to send it.
        </Text>
      )}

      <Box marginTop={1} gap={1} flexWrap="wrap">
        {judged.verdict === 'hold' && !isApproved && !isOutdated && (
          <Button
            key="approve"
            label="Approve commit"
            variant="primary"
            onPress={() => act.approve(judged.fingerprint)}
          />
        )}
        <Button
          key="codex"
          label={reviewed.status === 'running' ? 'Codex reviewing…' : 'Run Codex review'}
          onPress={async () => {
            if (reviewed.status !== 'running') {
              await act.codex()
            }
          }}
        />
        <Button
          key="rerun"
          label="Refresh assessment"
          {...(isOutdated ? { variant: 'primary' as const } : {})}
          onPress={async () => void (await act.triage())}
        />
      </Box>
      {view.isScrollHinted && (
        <Text dimColor wrap="wrap">
          Click the pane or press ctrl+x tab, then use the arrow keys to scroll to Why, Start with and the signals.
        </Text>
      )}

      {judged.reasons.length > 0 && heading('Why')}
      {judged.reasons.map(reason => (
        <Text wrap="wrap">· {reason}</Text>
      ))}

      {heading('Start with')}
      {startWith(judged.blast, flags).map(({ file, why }) => (
        <Box key={file.path}>
          <Box flexShrink={1}>
            <Text color="suggestion" wrap="truncate-start">
              {file.path}
            </Text>
          </Box>
          <Box flexGrow={1} flexShrink={2}>
            <Text dimColor wrap="truncate-end">
              {' '}· {why}
            </Text>
          </Box>
        </Box>
      ))}

      {reviewBox}

      <Box marginTop={1}>
        <Button
          key="details"
          plain
          dimColor
          label={isOpen ? '▾ Hide detailed signals' : '▸ Detailed signals'}
          onPress={() => act.toggleDetails()}
        />
      </Box>
      {isOpen && jev.status !== 'judged' && (
        <Text dimColor wrap="wrap">
          {jev.status === 'off'
            ? 'Jev is not configured: set the TypeSafe API key in /config or TYPESAFE_API_KEY.'
            : 'Jev gave no judgement this time; see the line under the change summary.'}
        </Text>
      )}
      {isOpen && jev.status === 'judged' && (
        <Box flexDirection="column">
          <Text dimColor wrap="wrap">
            {flags.length === 0 ? 'Jev flagged nothing in this diff.' : 'What Jev flagged in this diff, and where to look.'}
          </Text>
          {flags.map(flagged)}
          {(clear.length > 0 || testsNote !== undefined) && (
            <Box flexDirection="column" marginTop={1}>
              {clear.length > 0 && (
                <Text dimColor wrap="wrap">
                  Not flagged: {clear.join(', ')}.
                </Text>
              )}
              {testsNote !== undefined && (
                <Text dimColor wrap="wrap">
                  {testsNote}
                </Text>
              )}
            </Box>
          )}
        </Box>
      )}
      {isOpen && (
        <Box flexDirection="column">
          {heading('Diagnostics')}
          <Text dimColor wrap="wrap">
            {diagnosticsOf(judged)}
          </Text>
        </Box>
      )}
    </Box>
  )
}

