// The shell splitting is adapted from prismantis (MIT), hooks/render.tsx:
// https://github.com/NahumLitvin/prismantis
import type { Scope } from '../types'

/** With `paths`, the commit takes what was staged before plus what `git add` stages from those paths. */
export type CommitCall = { cwd?: string; scope: Scope; paths?: string[] }

const HEREDOC = /<<(?!<)-?\s*(['"]?)([A-Za-z_][\w-]*)\1/g
const SHELLS = new Set(['bash', 'sh', 'zsh', 'pwsh', 'powershell'])
const MOVES = new Set(['cd', 'pushd', 'set-location'])
const LEADING_KEYWORDS = new Set(['do', 'then', 'else', 'elif', 'if', 'while', 'until', '!', '{', 'time'])
const GIT_OPTIONS_WITH_VALUE = new Set(['-C', '-c', '--git-dir', '--work-tree', '--namespace', '--config-env'])

function dropHeredocBodies(command: string): string {
  const lines = command.split('\n')
  const kept: string[] = []

  for (let at = 0; at < lines.length; at += 1) {
    const line = lines[at] ?? ''
    kept.push(line)

    for (const [, , end] of line.matchAll(HEREDOC)) {
      while (at + 1 < lines.length && (lines[at + 1] ?? '').trim() !== end) {
        at += 1
      }

      at += 1
    }
  }

  return kept.join('\n')
}

export function segmentsOf(source: string, isPosix: boolean): string[][] {
  const command = dropHeredocBodies(source)
  const segments: string[][] = [[]]
  let word = ''
  let quote = ''
  let isStarted = false

  const endWord = () => {
    if (isStarted) {
      segments[segments.length - 1]?.push(word)
    }

    word = ''
    isStarted = false
  }
  const endSegment = () => {
    endWord()
    segments.push([])
  }

  for (let at = 0; at < command.length; at += 1) {
    const char = command[at] ?? ''
    const next = command[at + 1] ?? ''

    if (quote !== '') {
      if (char === quote) {
        quote = ''
      } else if (isPosix && char === '\\' && quote === '"' && /[$`"\\]/.test(next)) {
        word += next
        at += 1
      } else {
        word += char
      }
    } else if (char === '"' || char === "'") {
      quote = char
      isStarted = true
    } else if (isPosix && char === '\\' && next === '\n') {
      at += 1
    } else if (isPosix && char === '\\' && next !== '') {
      word += next
      isStarted = true
      at += 1
    } else if (char === '\n' || char === ';' || char === '|' || char === '&' || char === '(' || char === ')') {
      endSegment()
    } else if (/\s/.test(char)) {
      endWord()
    } else {
      word += char
      isStarted = true
    }
  }

  endWord()

  return segments.filter(words => words.length > 0)
}

const isAssignment = (word: string) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(word)

function commandWords(words: string[]): string[] {
  const from = words.findIndex(word => !isAssignment(word) && !LEADING_KEYWORDS.has(word))

  return from < 0 ? [] : words.slice(from)
}

const programOf = (word: string | undefined) =>
  (word ?? '')
    .replaceAll('\\', '/')
    .split('/')
    .pop()
    ?.replace(/\.exe$/i, '')
    .toLowerCase() ?? ''

const isAbsolute = (path: string) => /^([A-Za-z]:)?[\\/]/.test(path) || path.startsWith('~')

const under = (base: string | undefined, path: string | undefined) => {
  if (path === undefined) return base
  if (base === undefined || isAbsolute(path)) return path

  return `${base}/${path}`
}

function gitCall(args: string[]) {
  let dir: string | undefined
  let at = 0

  while (at < args.length && (args[at] ?? '').startsWith('-')) {
    const option = args[at] ?? ''

    if (option === '-C') {
      dir = under(dir, args[at + 1])
    }

    at += GIT_OPTIONS_WITH_VALUE.has(option) ? 2 : 1
  }

  return { dir, verb: args[at], rest: args.slice(at + 1) }
}

const COMMIT_OPTIONS_WITH_VALUE = /^(-[a-zA-Z]*[mFCct]|--(message|file|author|date|fixup|squash|template|cleanup|reuse-message|reedit-message|trailer))$/

const commitsAll = (word: string) => word === '--all' || /^-[a-zA-Z]*a[a-zA-Z]*$/.test(word)

/** A redirection such as `<<EOF`, `2>/dev/null` or `>`; a bare operator takes the next word as its target. */
const REDIRECT = /^\d*(<<?-?|>>?)/
const isBareRedirect = (word: string) => /^\d*(<<?-?|>>?)$/.test(word)

function commitsWorkingTree(args: string[]): boolean {
  for (let at = 0; at < args.length; at += 1) {
    const word = args[at] ?? ''

    if (REDIRECT.test(word)) {
      if (isBareRedirect(word)) at += 1
      continue
    }

    if (commitsAll(word) || word === '--' || /^(-[a-zA-Z]*[oi][a-zA-Z]*|--only|--include)$/.test(word)) return true
    if (COMMIT_OPTIONS_WITH_VALUE.test(word)) at += 1
    else if (!word.startsWith('-')) return true
  }

  return false
}

type Added = { scope: Scope; paths: string[] }

/** What `git add` stages. Anything it cannot place exactly counts as the whole tree. */
function addedBy(args: string[]): Added {
  const paths: string[] = []
  let isUpdate = false
  let isAll = false

  for (let at = 0; at < args.length; at += 1) {
    const word = args[at] ?? ''

    if (word === '--') {
      paths.push(...args.slice(at + 1))
      break
    }

    if (!word.startsWith('-')) paths.push(word)
    else if (word === '-u' || word === '--update') isUpdate = true
    else if (word === '-A' || word === '--all') isAll = true
    else if (/^(-[a-zA-Z]*[pie][a-zA-Z]*|--(patch|interactive|edit)|--pathspec-from-file.*)$/.test(word))
      return { scope: 'tree', paths: [] }
  }

  if (paths.length > 0) return { scope: 'tree', paths }

  return { scope: isUpdate && !isAll ? 'tracked' : 'tree', paths: [] }
}

/** The union of the adds before a commit; one that reaches the whole tree, or runs from another folder, wins. */
function joinAdds(adds: (Added & { dir?: string })[], commitDir: string | undefined): Pick<CommitCall, 'scope' | 'paths'> {
  if (adds.length === 0) return { scope: 'tree' }
  if (adds.some(add => add.paths.length === 0 || add.dir !== commitDir)) {
    return { scope: adds.every(add => add.scope === 'tracked' && add.dir === commitDir) ? 'tracked' : 'tree' }
  }

  return { scope: 'tree', paths: adds.flatMap(add => add.paths) }
}

export function commitIn(command: string, isPosix = true, cwd?: string): CommitCall | undefined {
  let dir = cwd
  const adds: (Added & { dir?: string })[] = []

  for (const words of segmentsOf(command, isPosix)) {
    const [name, ...rest] = commandWords(words)
    const program = programOf(name)

    if (MOVES.has(program)) {
      dir = under(dir, rest.find(word => !word.startsWith('-')))
    } else if (SHELLS.has(program)) {
      const script = rest[rest.findIndex(word => /^-(c|command)$/i.test(word)) + 1]
      const inner = script === undefined ? undefined : commitIn(script, isPosix, dir)

      if (inner !== undefined) return inner
    } else if (program === 'git') {
      const call = gitCall(rest)

      if (call.verb === 'add') adds.push({ ...addedBy(call.rest), dir: under(dir, call.dir) })

      if (call.verb === 'commit') {
        const commitDir = under(dir, call.dir)

        if (adds.length === 0) return { cwd: commitDir, scope: commitsWorkingTree(call.rest) ? 'tracked' : 'staged' }
        if (commitsWorkingTree(call.rest)) return { cwd: commitDir, scope: 'tree' }

        return { cwd: commitDir, ...joinAdds(adds, commitDir) }
      }
    }
  }

  return undefined
}

files.hooks/verdict.ts:
import type { Blast, Flag, Jev, Place, Verdict } from '../types'
import { SENSITIVE_PATH, groupsOf } from './blast'
import { placeText } from './jev'

const MANY_LINES = 400
const SOME_LINES = 150
const MANY_FILES = 10
const SOME_FILES = 5
const MANY_AREAS = 4
const WIDE_USE = 10
const SOME_USE = 4
const LIKELY = 0.7
const UNSURE = 0.4
const UNLIKELY = 0.3
const HARD = 0.5
const EFFORTFUL = 0.25
const HOLD_AT = 5
const READ_AT = 2

const SENSITIVE = ['security', 'data', 'money', 'concurrency', 'publicApi']

/** Each kind of signal counts up to a cap, so a hold needs more than one kind to agree. */
const CAPS = { size: 3, reach: 2, risk: 2, quality: 2 }

export const percent = (value: number) => `${Math.round(value * 100)}%`

/** How likely, in a word: `/gate details` leads with it and gives the number after. */
export const likelihood = (value: number) => (value >= LIKELY ? 'likely' : value >= UNLIKELY ? 'possible' : 'unlikely')

/**
 * The Jev signals that fired, each with the file to look at. A change in behaviour alone is not one: nearly every diff
 * has it. It fires only when no tests in the diff cover it.
 */
export function flagsOf(blast: Blast, jev: Jev): Flag[] {
  if (jev.status !== 'judged') {
    return []
  }

  const find = (key: string) => jev.judgments.find(one => one.key === key)
  const where = (at: Place | undefined) => (at === undefined ? {} : { at })
  const flags: Flag[] = jev.judgments
    .filter(one => SENSITIVE.includes(one.key) && one.value >= UNSURE)
    .map(one => ({
      key: one.key,
      label: one.label,
      said: one.value >= LIKELY ? `likely touches ${one.label}` : `may touch ${one.label}`,
      isLikely: one.value >= LIKELY,
      ...where(one.at),
    }))
  const behaviour = find('behaviour')

  if ((behaviour?.value ?? 0) >= LIKELY && (find('tested')?.value ?? 1) < UNLIKELY) {
    flags.push({
      key: 'untested',
      label: 'untested behaviour change',
      said: 'changes behaviour without tests for it',
      isLikely: true,
      ...where(behaviour?.at),
    })
  }

  if (jev.hardToRead >= EFFORTFUL) {
    const isHard = jev.hardToRead >= HARD
    flags.push({
      key: 'readability',
      label: 'hard to follow',
      said: isHard ? 'hard to follow' : 'parts take effort to follow',
      isLikely: isHard,
      ...where(jev.hardestAt),
    })
  }

  if ((find('mixed')?.value ?? 0) >= LIKELY) {
    const groups = groupsOf(blast.files)
    flags.push({
      key: 'mixed',
      label: 'mixes changes',
      said: 'mixes unrelated changes',
      isLikely: true,
      ...(groups.length > 1 ? { groups } : {}),
    })
  }

  return flags
}

export const groupsLine = (groups: { name: string; files: number }[]) =>
  groups.map(({ name, files }) => `${name} (${files} ${files === 1 ? 'file' : 'files'})`).join(' · ')

/** A fired signal as one line of the Why list: what and where, never a percentage. */
export function reasonOf(flag: Flag) {
  if (flag.key === 'mixed') {
    return `Jev: ${flag.said}${flag.groups === undefined ? '' : `: ${groupsLine(flag.groups)}`}; splitting it would help`
  }

  return `Jev: ${flag.said}${flag.at === undefined ? '' : `, mostly in ${placeText(flag.at)}`}`
}

/** The risk topics Jev checked and found nothing in, for one quiet line. */
export const clearOf = (jev: Jev) =>
  jev.status === 'judged' ? jev.judgments.filter(one => SENSITIVE.includes(one.key) && one.value < UNSURE).map(one => one.label) : []

/** What Jev said about tests, when it is not already a flag. */
export function testsNoteOf(jev: Jev) {
  if (jev.status !== 'judged') return undefined

  const value = (key: string) => jev.judgments.find(one => one.key === key)?.value
  const tested = value('tested') ?? 0
  const behaviour = value('behaviour') ?? 0

  if (tested >= LIKELY) return 'Tests in the diff exercise the change.'
  if (behaviour >= LIKELY && tested >= UNLIKELY) return 'Unclear whether the tests in the diff cover the change.'

  return undefined
}

export function verdictOf(blast: Blast, jev: Jev) {
  const reasons: string[] = []
  const tally = { size: 0, reach: 0, risk: 0, quality: 0 }
  const add = (kind: keyof typeof CAPS, weight: number, reason: string) => {
    tally[kind] = Math.min(CAPS[kind], tally[kind] + weight)
    reasons.push(reason)
  }

  if (blast.lines >= MANY_LINES) add('size', 2, `${blast.lines} lines changed`)
  else if (blast.lines >= SOME_LINES) add('size', 1, `${blast.lines} lines changed`)

  if (blast.files.length >= MANY_FILES) add('size', 2, `${blast.files.length} files changed`)
  else if (blast.files.length >= SOME_FILES) add('size', 1, `${blast.files.length} files changed`)

  if (blast.areas.length >= MANY_AREAS) add('size', 1, `spans ${blast.areas.length} areas: ${blast.areas.join(', ')}`)

  const used = blast.widest?.usedBy ?? 0

  if (blast.widest !== undefined && used >= WIDE_USE) add('reach', 2, `${blast.widest.path} is used by ${used} other files`)
  else if (blast.widest !== undefined && used >= SOME_USE) add('reach', 1, `${blast.widest.path} is used by ${used} other files`)

  if (blast.risky.length > 0) add('reach', 1, `touches build, config or schema: ${blast.risky.join(', ')}`)

  for (const flag of flagsOf(blast, jev)) {
    const isRisk = SENSITIVE.includes(flag.key)
    const weight = (isRisk || flag.key === 'readability') && flag.isLikely ? 2 : 1

    add(isRisk ? 'risk' : 'quality', weight, reasonOf(flag))
  }

  // Consequence is judged apart from size: a small change to sensitive code is never a pass.
  const sensitive = blast.files.filter(file => SENSITIVE_PATH.test(file.path)).map(file => file.path)
  const security = jev.status === 'judged' ? jev.judgments.find(one => one.key === 'security')?.value ?? 0 : 0

  if (sensitive.length > 0) reasons.push(`changes sensitive code: ${sensitive.join(', ')}`)
  if (security >= LIKELY) reasons.push('held for review because Jev judges it likely to touch security')

  const points = tally.size + tally.reach + tally.risk + tally.quality
  const bySize: Verdict = points >= HOLD_AT ? 'hold' : points >= READ_AT ? 'read' : 'pass'
  const verdict: Verdict = security >= LIKELY ? 'hold' : sensitive.length > 0 && bySize === 'pass' ? 'read' : bySize

  return { verdict, points, reasons }
}

